import{_ as o,o as t,c,a5 as d}from"./chunks/framework.BfQ7H7Qx.js";const h=JSON.parse('{"title":"Plan — FR 3.8.6: Schedule Platform Post (UC-112)","description":"","frontmatter":{},"headers":[],"relativePath":"feature/srs/07-publishing-social/3-8-6-schedule-platform-post/plan.md","filePath":"feature/srs/07-publishing-social/3-8-6-schedule-platform-post/plan.md"}'),a={name:"feature/srs/07-publishing-social/3-8-6-schedule-platform-post/plan.md"};function s(r,e,n,i,l,u){return t(),c("div",null,[...e[0]||(e[0]=[d('<p>&gt; <strong>Navigation:</strong> <a href="./../README.html">← Domain Index</a> · <a href="./spec.html">Spec</a> · <strong>Plan</strong> · <a href="./task.html">Task</a> · <a href="./test.html">Test</a></p><h1 id="plan-—-fr-3-8-6-schedule-platform-post-uc-112" tabindex="-1">Plan — FR 3.8.6: Schedule Platform Post (<code>UC-112</code>) <a class="header-anchor" href="#plan-—-fr-3-8-6-schedule-platform-post-uc-112" aria-label="Permalink to &quot;Plan — FR 3.8.6: Schedule Platform Post (`UC-112`)&quot;">​</a></h1><h2 id="_1-architectural-scope-touched-repositories" tabindex="-1">1. Architectural Scope &amp; Touched Repositories <a class="header-anchor" href="#_1-architectural-scope-touched-repositories" aria-label="Permalink to &quot;1. Architectural Scope &amp; Touched Repositories&quot;">​</a></h2><p>Implements <strong>FR 3.8.6 — Schedule Platform Post</strong> (<a href="./spec.html">spec.md</a>) for canonical roles <code>Owner, Manager, Creator</code> across the BrandHub social publishing architecture:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Layer / Repository</th><th style="text-align:left;">Concrete Classes, Queues &amp; Files</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>API Gateway (<code>brandhub-api-gateway</code>)</strong></td><td style="text-align:left;"><code>InboundSecurityWebFilter.java</code>, <code>JwtAuthFilterGatewayFilterFactory.java</code>, OAuth callback &amp; <code>/api/v1/social/**</code> / <code>/api/v1/workspaces/**</code> routing</td></tr><tr><td style="text-align:left;"><strong>Business Service (<code>brandhub-business-service</code>)</strong></td><td style="text-align:left;"><code>PostController.java</code>, <code>SocialAccountController.java</code>, <code>TaskPostController.java</code>, <code>InternalPostController.java</code>, <code>PostService.java</code>, <code>PostPublishService.java</code>, <code>SocialAccountService.java</code>, <code>RabbitMQConfig.java</code></td></tr><tr><td style="text-align:left;"><strong>Publisher Service (<code>brandhub-publisher-service</code>)</strong></td><td style="text-align:left;"><code>SocialOAuthController.java</code>, <code>PublishJobConsumer.java</code>, <code>RabbitMQConfig.java</code>, <code>CryptoUtils.java</code>, <code>FacebookPublishServiceImpl.java</code>, <code>InstagramPublishServiceImpl.java</code>, <code>TikTokPublishServiceImpl.java</code>, <code>TikTokCreatorUploadService.java</code>, <code>ThreadsPublishServiceImpl.java</code>, <code>TokenRefreshScheduler.java</code></td></tr><tr><td style="text-align:left;"><strong>Data, Cache &amp; Broker Layer</strong></td><td style="text-align:left;">MongoDB <code>social_accounts</code> (<code>SocialAccountDocument</code>), MongoDB <code>posts</code> (<code>PostDocument</code>), Redis lock <code>processingPostIds:{postId}:{platform}</code> (<code>TTL = 30m</code>), RabbitMQ <code>publisher.job.exchange</code> -&gt; <code>publisher.job.queue</code> + <code>publish.jobs.retry.1m/5m/15m</code> + <code>publisher.job.dlq</code>, PostgreSQL <code>user_notifications</code></td></tr><tr><td style="text-align:left;"><strong>Web Application (<code>brandhub-web</code>)</strong></td><td style="text-align:left;"><code>pages/editor/components/ScheduleModal.tsx</code>, <code>pages/calendar/components/SchedulePostModal.tsx</code>, <code>ContentCalendar.tsx</code></td></tr><tr><td style="text-align:left;"><strong>Mobile App (<code>brandhub-mobile-app</code>)</strong></td><td style="text-align:left;"><code>src/screens/calendar/CalendarScreen.tsx</code>, <code>src/components/calendar/CalendarModals.tsx</code></td></tr><tr><td style="text-align:left;"><strong>i18n Locale Bundles</strong></td><td style="text-align:left;">Web: <code>editor.schedule.title</code>, <code>editor.schedule.recommendedSlots</code>, <code>editor.schedule.timezoneHint</code>, <code>editor.schedule.errors.pastTime</code> in <code>vi.json</code> &amp; <code>en.json</code>; Mobile: <code>src/i18n/locales/en.json</code> + <code>src/i18n/locales/vi/common.json</code> (<code>tr()</code>)</td></tr></tbody></table><h2 id="_2-persistence-token-cryptography-messaging-topology" tabindex="-1">2. Persistence, Token Cryptography &amp; Messaging Topology <a class="header-anchor" href="#_2-persistence-token-cryptography-messaging-topology" aria-label="Permalink to &quot;2. Persistence, Token Cryptography &amp; Messaging Topology&quot;">​</a></h2><ol><li><strong>MongoDB Document Schemas:</strong><ul><li><code>social_accounts</code> (<code>SocialAccountDocument</code>): Indexed by <code>{workspaceId, platform, platformAccountId}</code>; stores AES-256-GCM encrypted token ciphertext (<code>CryptoUtils</code>), <code>tokenExpiresAt</code>, <code>status</code> (<code>CONNECTED</code>, <code>TOKEN_EXPIRED</code>, <code>DISCONNECTED</code>), and display profile snapshot.</li><li><code>posts</code> (<code>PostDocument</code>): Indexed by <code>{workspaceId, status, scheduledAt}</code> and <code>{workspaceId, taskId}</code>; stores caption, hashtags, media references, <code>scheduledAt</code>, aggregate status, and per-platform <code>PlatformDeliveryTarget</code> subdocuments (<code>placement</code>, <code>status</code>, <code>externalPostId</code>, <code>permalinkUrl</code>, <code>retryCount</code>, <code>lastError</code>).</li></ul></li><li><strong>RabbitMQ Resilient Delivery (<code>brandhub.publishing</code>):</strong><ul><li>Primary exchange <code>publisher.job.exchange</code> routes <code>PublishJobMessage</code> to durable queue <code>publisher.job.queue</code> (<code>DefaultClassMapper</code> maps <code>com.brandhub.business.dto.message.PublishJobMessage</code> cleanly to <code>com.brandhub.publisher.core.dto.PublishJobMessage</code>).</li><li>Transient upstream <code>429/5xx</code> errors publish with incremented <code>x-retry-count</code> to <code>publisher.retry.exchange</code> -&gt; <code>publish.jobs.retry.1m</code> (<code>60,000 ms</code>), <code>publish.jobs.retry.5m</code> (<code>300,000 ms</code>), <code>publish.jobs.retry.15m</code> (<code>900,000 ms</code>), dead-lettering back to <code>publisher.job.exchange</code>, and finally <code>publisher.job.dlx</code> -&gt; <code>publisher.job.dlq</code> on permanent failure or retry exhaustion.</li></ul></li></ol><h2 id="_3-end-to-end-execution-flow" tabindex="-1">3. End-to-End Execution Flow <a class="header-anchor" href="#_3-end-to-end-execution-flow" aria-label="Permalink to &quot;3. End-to-End Execution Flow&quot;">​</a></h2><ol><li><strong>Actor Trigger:</strong> Authenticated user (<code>Owner, Manager, Creator</code>) invokes <code>Schedule Platform Post</code> on Web or Mobile.</li><li><strong>Authorization &amp; Validation:</strong> <code>brandhub-business-service</code> (or <code>SocialOAuthController</code> delegating to <code>/api/v1/internal/social-accounts/authorize-connect</code>) verifies <code>Owner, Manager, Creator</code> membership in <code>workspaceId</code> and validates platform/media/schedule rules (<code>BR-20, BR-56, BR-57</code>).</li><li><strong>Synchronous Query or Async Broker Fan-Out:</strong> Read/preview/OAuth actions complete synchronously with <code>ApiResponse&lt;T&gt;</code>; publish/schedule actions persist <code>PostDocument</code> state, dispatch per-platform <code>PublishJobMessage</code> to RabbitMQ, acquire Redis <code>processingPostIds:{postId}:{platform}</code>, invoke Meta/TikTok/Threads HTTPS APIs, and callback <code>InternalPostController</code> (<code>X-Internal-Service-Key</code>).</li><li><strong>Client State Update:</strong> <code>TanStack Query</code> refreshes post/account views and PostgreSQL <code>LISTEN/NOTIFY</code> delivers realtime <code>user_notifications</code> upon completion or failure.</li></ol><h2 id="_4-sequential-build-order" tabindex="-1">4. Sequential Build Order <a class="header-anchor" href="#_4-sequential-build-order" aria-label="Permalink to &quot;4. Sequential Build Order&quot;">​</a></h2><ol><li><strong>Step 1 — Contracts &amp; MongoDB Indexes:</strong> Verify <code>SocialAccountDocument</code> / <code>PostDocument</code> indexes, DTO validation annotations, and <code>PublishJobMessage</code> Jackson type mappings.</li><li><strong>Step 2 — Publisher Adapter / OAuth Service:</strong> Implement &amp; unit-test provider HTTP interactions (<code>RestClient</code> / <code>WebClient</code>), PKCE/state validation, <code>CryptoUtils</code> AES-256-GCM encryption, and <code>ErrorClassifier</code> retry vs permanent failure rules.</li><li><strong>Step 3 — Business Service Controllers &amp; Callbacks:</strong> Wire <code>PostController</code>, <code>SocialAccountController</code>, and <code>InternalPostController</code> with <code>@RequireRole</code> and <code>X-Internal-Service-Key</code> guards.</li><li><strong>Step 4 — Web &amp; Mobile UI:</strong> Build/wire <code>pages/editor/components/ScheduleModal.tsx</code>, <code>pages/calendar/components/SchedulePostModal.tsx</code>, <code>ContentCalendar.tsx</code> and <code>src/screens/calendar/CalendarScreen.tsx</code>, <code>src/components/calendar/CalendarModals.tsx</code> with loading/empty/error states and platform-accurate mockups.</li><li><strong>Step 5 — i18n (<code>vi.json</code> + <code>en.json</code>) &amp; Light/Dark Theme:</strong> Synchronize <code>editor.schedule.title</code>, <code>editor.schedule.recommendedSlots</code>, <code>editor.schedule.timezoneHint</code>, <code>editor.schedule.errors.pastTime</code> in <code>vi.json</code> &amp; <code>en.json</code> and verify Light/Dark semantic tokens across <code>375px / 768px / 1440px</code>.</li><li><strong>Step 6 — Verification:</strong> Execute JUnit 5 MockMvc/WireMock tests, RabbitMQ/Redis consumer tests, Jest mobile tests, and Playwright E2E checks (<a href="./test.html">test.md</a>).</li></ol><h2 id="_5-localization-vi-json-en-json-theme-tokens-api-envelope-contract" tabindex="-1">5. Localization (<code>vi.json</code> + <code>en.json</code>), Theme Tokens &amp; API Envelope Contract <a class="header-anchor" href="#_5-localization-vi-json-en-json-theme-tokens-api-envelope-contract" aria-label="Permalink to &quot;5. Localization (`vi.json` + `en.json`), Theme Tokens &amp; API Envelope Contract&quot;">​</a></h2><ul><li><strong>Standardized <code>ApiResponse&lt;T&gt;</code> Contract:</strong> All JSON endpoints return <code>{ &quot;success&quot;: boolean, &quot;data&quot;: T, &quot;error&quot;: { &quot;code&quot;, &quot;message&quot; } | null, &quot;requestId&quot;: string }</code> with deterministic HTTP status mapping (<code>200/201/204</code> success; <code>400</code> validation; <code>401</code> unauthenticated; <code>402</code> insufficient credit; <code>403</code> role/tenant forbidden; <code>404</code> scoped not found; <code>409</code> version/idempotency conflict; <code>429</code> rate limit; <code>503</code> upstream unavailable).</li><li><strong>Key-Parallel i18n Synchronization:</strong> All UI strings are added simultaneously in <code>vi.json</code> and <code>en.json</code> on <code>brandhub-web</code> and mirrored via <code>tr()</code> (<code>src/i18n/locales/en.json</code> + <code>src/i18n/locales/vi/common.json</code>) on <code>brandhub-mobile-app</code> — zero hardcoded Vietnamese or English text in JSX/TSX.</li><li><strong>Semantic Light &amp; Dark Mode Styling:</strong> Web components use CSS custom properties and Tailwind <code>dark:</code> variants; Mobile screens use <code>useAppPreferences().palette</code> (<code>src/theme/tokens.ts</code>), maintaining WCAG AA contrast across Light and Dark modes.</li></ul><h2 id="_6-engineering-risks-mitigations" tabindex="-1">6. Engineering Risks &amp; Mitigations <a class="header-anchor" href="#_6-engineering-risks-mitigations" aria-label="Permalink to &quot;6. Engineering Risks &amp; Mitigations&quot;">​</a></h2><ul><li><strong>Duplicate Social Posts on Broker Redelivery:</strong> Mitigated by per-<code>(postId, platform)</code> Redis <code>SETNX</code> lock (<code>processingPostIds:{postId}:{platform}</code>) and idempotent status checks before calling external APIs.</li><li><strong>Client Media Stream Aborts (<code>Broken pipe</code> / <code>AsyncRequestNotUsableException</code>):</strong> Handled gracefully as client disconnect debug events without polluting <code>500</code> alerting (see <code>social-publisher-resilience</code>).</li><li><strong>OAuth Token Expiry Before Scheduled Time:</strong> Mitigated by <code>TokenRefreshScheduler</code> refreshing tokens expiring within <code>7</code> days and surfacing proactive reconnect banners.</li></ul>',15)])])}const g=o(a,[["render",s]]);export{h as __pageData,g as default};
